window.CIVIL_SET_DATA["past-11"] = {"title":"Past Paper Set 11","negativeMarking":0,"chapters":[{"name":"Basic Civil Engineering","questions":[{"id":"PAST-11-003","src":"PAST-11-003","text":"What is the minimum number of GPS satellites used?","options":[{"key":"a","text":"54"},{"key":"b","text":"12"},{"key":"c","text":"5"},{"key":"d","text":"24"}],"answer":"d","explanation":"The GPS constellation needs a minimum of 24 operational satellites to give global coverage. A receiver then needs at least four in view for a 3-D fix.","marks":1,"source":{"kind":"past","set":11,"question":3,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q3 · 1 mark"},"topic":"ACiE0105"},{"id":"PAST-11-005","src":"PAST-11-005","text":"The moment of inertia of a semicircle about its base is","options":[{"key":"a","text":"\\(\\dfrac{\\pi R^4}{4}\\)"},{"key":"b","text":"\\(\\dfrac{\\pi R^4}{8}\\)"},{"key":"c","text":"\\(R^4\\left(\\dfrac{\\pi}{8} - \\dfrac{8}{9\\pi}\\right)\\)"},{"key":"d","text":"\\(0.11R^4\\)"}],"answer":"b","explanation":"About its diameter (base), a semicircle has half the full circle's \\(\\dfrac{\\pi R^4}{4}\\): \\[I = \\dfrac{\\pi R^4}{8}\\] Options (c) and (d) are its centroidal value, \\[R^4\\left(\\dfrac{\\pi}{8} - \\dfrac{8}{9\\pi}\\right) \\approx 0.11R^4\\]","marks":1,"source":{"kind":"past","set":11,"question":5,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q5 · 1 mark"},"topic":"ACiE0104"},{"id":"PAST-11-007","src":"PAST-11-007","text":"Which of the following is not a type of load-bearing wall?","options":[{"key":"a","text":"Solid masonry wall"},{"key":"b","text":"Panel wall"},{"key":"c","text":"Cavity wall"},{"key":"d","text":"Faced wall"}],"answer":"b","explanation":"A panel (curtain or infill) wall only fills the space between the frame members of a framed building and carries just its own weight. Solid, cavity and faced walls can be load-bearing.","marks":1,"source":{"kind":"past","set":11,"question":7,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q7 · 1 mark"},"topic":"ACiE0103"},{"id":"PAST-11-008","src":"PAST-11-008","text":"Before plastering, the surface has to be","options":[{"key":"a","text":"rough"},{"key":"b","text":"smooth"},{"key":"c","text":"cemented"},{"key":"d","text":"watered"}],"answer":"a","explanation":"The background is roughened (joints raked out) and then wetted so that the plaster keys in and bonds firmly.","marks":1,"source":{"kind":"past","set":11,"question":8,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q8 · 1 mark"},"topic":"ACiE0103"},{"id":"PAST-11-023","src":"PAST-11-023","text":"Plastic bitumen is generally used for","options":[{"key":"a","text":"expansion joint"},{"key":"b","text":"road pavement"},{"key":"c","text":"paints"},{"key":"d","text":"filling cracks"}],"answer":"d","explanation":"Plastic bitumen (bitumen with thinner and inert filler) is a plastic filler used for filling cracks in masonry and for stopping leaks.","marks":1,"source":{"kind":"past","set":11,"question":23,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q23 · 1 mark"},"topic":"ACiE0101"},{"id":"PAST-11-024","src":"PAST-11-024","text":"The final setting time of OPC is","options":[{"key":"a","text":"10 min"},{"key":"b","text":"30 min"},{"key":"c","text":"6 hours"},{"key":"d","text":"10 hours"}],"answer":"d","explanation":"IS 269 allows OPC a maximum final setting time of 600 minutes (10 hours). The minimum initial setting time is 30 minutes.","marks":1,"source":{"kind":"past","set":11,"question":24,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q24 · 1 mark"},"topic":"ACiE0101"},{"id":"PAST-11-033","src":"PAST-11-033","text":"Which of the following is an enlarging scale?","options":[{"key":"a","text":"1:5"},{"key":"b","text":"5:1"},{"key":"c","text":"1:3"},{"key":"d","text":"1:10"}],"answer":"b","explanation":"A scale of 5:1 draws objects five times their true size, which is enlarging. Scales such as 1:5, 1:3 and 1:10 are reducing scales.","marks":1,"source":{"kind":"past","set":11,"question":33,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q33 · 1 mark"},"topic":"ACiE0105"},{"id":"PAST-11-061","src":"PAST-11-061","text":"The permissible error (\\(E\\)) for the precise levelling type with distance (\\(D\\)) in kilometres is given by","options":[{"key":"a","text":"\\(E = \\pm 0.025\\sqrt{D}\\)"},{"key":"b","text":"\\(E = \\pm 0.100\\sqrt{D}\\)"},{"key":"c","text":"\\(E = \\pm 0.012\\sqrt{D}\\)"},{"key":"d","text":"\\(E = \\pm 0.006\\sqrt{D}\\)"}],"answer":"d","explanation":"The permissible closing error in metres, with \\(D\\) in km, is \\(\\pm 0.100\\sqrt{D}\\) for rough, \\(\\pm 0.025\\sqrt{D}\\) for ordinary, \\(\\pm 0.012\\sqrt{D}\\) for accurate and \\[E = \\pm 0.006\\sqrt{D}\\] for precise levelling.","marks":2,"source":{"kind":"past","set":11,"question":61,"marks":2,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q61 · 2 marks"},"topic":"ACiE0105"},{"id":"PAST-11-062","src":"PAST-11-062","text":"The ratio of the MOI about a line passing through the CG to that about the top (apex) of a triangular section is","options":[{"key":"a","text":"4:1"},{"key":"b","text":"1:3"},{"key":"c","text":"1:4"},{"key":"d","text":"1:9"}],"answer":"d","explanation":"The centroidal value is \\(I_G = \\dfrac{bh^3}{36}\\). About the line through the apex parallel to the base, \\[\\begin{aligned} I &amp;= \\dfrac{bh^3}{36} + \\dfrac{bh}{2}\\left(\\dfrac{2h}{3}\\right)^2 \\\\ &amp;= \\dfrac{bh^3}{4} \\end{aligned}\\] so the ratio is 1:9.","marks":2,"source":{"kind":"past","set":11,"question":62,"marks":2,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q62 · 2 marks"},"topic":"ACiE0104"},{"id":"PAST-11-070","src":"PAST-11-070","text":"Find the number of bags of cement required to make 2 m<sup>3</sup> of concrete of density 2390 kg/m<sup>3</sup>. The weight of aggregate used (FA+CA) is 3800 kg and the w/c ratio is 0.4.","options":[{"key":"a","text":"12 bags"},{"key":"b","text":"13 bags"},{"key":"c","text":"14 bags"},{"key":"d","text":"17 bags"}],"answer":"c","explanation":"The total mass is \\(2 \\times 2390 = 4780\\) kg, so cement plus water is 980 kg. With water \\(= 0.4C\\), \\[1.4C = 980 \\;\\Rightarrow\\; C = 700\\ \\text{kg}\\] or 14 bags.","marks":2,"source":{"kind":"past","set":11,"question":70,"marks":2,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q70 · 2 marks"},"topic":"ACiE0106"}]},{"name":"Soil Mechanics and Foundation Engineering","questions":[{"id":"PAST-11-001","src":"PAST-11-001","text":"The dilatancy test is used to identify","options":[{"key":"a","text":"fine grained soil"},{"key":"b","text":"coarse grained soils"},{"key":"c","text":"all types of soil"},{"key":"d","text":"organic soil"}],"answer":"a","explanation":"The dilatancy (shaking) test is a field identification test for fine-grained soils. Water appears on shaking and disappears on squeezing in silts (quick reaction) but not in clays, so it separates silts from clays.","marks":1,"source":{"kind":"past","set":11,"question":1,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q1 · 1 mark"},"topic":"ACiE0201"},{"id":"PAST-11-002","src":"PAST-11-002","text":"The maximum size of grain of silt is about","options":[{"key":"a","text":"0.06 mm"},{"key":"b","text":"0.2 mm"},{"key":"c","text":"0.5 mm"},{"key":"d","text":"1 mm"}],"answer":"a","explanation":"Silt ranges from about 0.002 mm to 0.06–0.075 mm (0.06 mm in the MIT/BS systems, 0.075 mm in IS). Coarser grains are sand.","marks":1,"source":{"kind":"past","set":11,"question":2,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q2 · 1 mark"},"topic":"ACiE0201"},{"id":"PAST-11-014","src":"PAST-11-014","text":"Which soil is formed by the deposition of silt brought down by the rivers?","options":[{"key":"a","text":"Black soil"},{"key":"b","text":"Red soil"},{"key":"c","text":"Alluvial soil"},{"key":"d","text":"Forest soil"}],"answer":"c","explanation":"Alluvial soils are transported soils deposited by rivers on their flood plains and deltas.","marks":1,"source":{"kind":"past","set":11,"question":14,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q14 · 1 mark"},"topic":"ACiE0201"},{"id":"PAST-11-015","src":"PAST-11-015","text":"When two column loads are unequal, which of the possible footings can be provided?","options":[{"key":"a","text":"Strap footing"},{"key":"b","text":"Raft footing"},{"key":"c","text":"Trapezoidal combined footing"},{"key":"d","text":"Mat footing"}],"answer":"c","explanation":"A trapezoidal combined footing is made wider under the heavier column. This brings the centroid of its area under the resultant load and gives uniform bearing pressure.","marks":1,"source":{"kind":"past","set":11,"question":15,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q15 · 1 mark"},"topic":"ACiE0205"},{"id":"PAST-11-036","src":"PAST-11-036","text":"A raft foundation is called a floating foundation when","options":[{"key":"a","text":"it is a normal foundation which can rise and float during floods"},{"key":"b","text":"it floats on water like barges"},{"key":"c","text":"the new loads due to the structure are equal to the weight of the soil removed by excavation"},{"key":"d","text":"it cannot be floating type under any condition"}],"answer":"c","explanation":"In a floating (compensated) raft, the weight of excavated soil balances the building load, so the net increase in pressure on the soil is nearly zero and settlement is small.","marks":1,"source":{"kind":"past","set":11,"question":36,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q36 · 1 mark"},"topic":"ACiE0205"},{"id":"PAST-11-063","src":"PAST-11-063","text":"According to Rankine's formula, the minimum depth of foundation when \\(q = 180\\) kN/m<sup>2</sup>, \\(\\gamma = 20\\) kN/m<sup>3</sup> and \\(\\phi = 30^\\circ\\) is","options":[{"key":"a","text":"1.0 m"},{"key":"b","text":"0.75 m"},{"key":"c","text":"0.50 m"},{"key":"d","text":"2.0 m"}],"answer":"a","explanation":"Rankine's minimum depth is \\[D_{min} = \\dfrac{q}{\\gamma}\\left(\\dfrac{1 - \\sin\\phi}{1 + \\sin\\phi}\\right)^2\\] \\[= \\dfrac{180}{20}\\left(\\dfrac{1}{3}\\right)^2 = 1.0\\ \\text{m}\\]","marks":2,"source":{"kind":"past","set":11,"question":63,"marks":2,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q63 · 2 marks"},"topic":"ACiE0205"},{"id":"PAST-11-064","src":"PAST-11-064","text":"An infinite slope is made with sand having an internal friction angle of 36°. What should be the maximum slope angle for a factor of safety of 1.5?","options":[{"key":"a","text":"54°"},{"key":"b","text":"36°"},{"key":"c","text":"26°"},{"key":"d","text":"24°"}],"answer":"c","explanation":"Since \\(\\text{FS} = \\dfrac{\\tan\\phi}{\\tan\\beta}\\), \\[\\tan\\beta = \\dfrac{\\tan 36^\\circ}{1.5} = 0.484\\] and \\(\\beta \\approx 26^\\circ\\).","marks":2,"source":{"kind":"past","set":11,"question":64,"marks":2,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q64 · 2 marks"},"topic":"ACiE0203"}]},{"name":"Basic Water Resources Engineering","questions":[{"id":"PAST-11-012","src":"PAST-11-012","text":"What type of material is most likely to be transported as suspended load?","options":[{"key":"a","text":"Clay"},{"key":"b","text":"Silt"},{"key":"c","text":"Sand"},{"key":"d","text":"Depends on the energy of the stream"}],"answer":"d","explanation":"Whether a particle stays in suspension depends on the stream's turbulence (energy) compared with the particle's fall velocity. A powerful flood can suspend sand, while a sluggish stream carries only clay.","marks":1,"source":{"kind":"past","set":11,"question":12,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q12 · 1 mark"},"topic":"ACiE0306"},{"id":"PAST-11-018","src":"PAST-11-018","text":"In a parallel combination of pipes, which of the following holds?","options":[{"key":"a","text":"Discharge is same in all pipes"},{"key":"b","text":"Head loss is same in all pipes"},{"key":"c","text":"Total head loss is sum of head loss in each pipe"},{"key":"d","text":"Velocity is same in all pipes"}],"answer":"b","explanation":"Pipes in parallel connect the same two junctions, so each has the same head loss and their discharges add up. For pipes in series the discharge is common and the losses add.","marks":1,"source":{"kind":"past","set":11,"question":18,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q18 · 1 mark"},"topic":"ACiE0304"},{"id":"PAST-11-022","src":"PAST-11-022","text":"As the duration of the unit hydrograph increases,","options":[{"key":"a","text":"the base period also increases"},{"key":"b","text":"peak ordinate decreases"},{"key":"c","text":"the base period decreases"},{"key":"d","text":"both a and b"}],"answer":"d","explanation":"The same 1 cm of runoff spread over a longer rainfall duration gives a longer base period. The area under the curve is fixed, so the peak ordinate falls.","marks":1,"source":{"kind":"past","set":11,"question":22,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q22 · 1 mark"},"topic":"ACiE0306"},{"id":"PAST-11-025","src":"PAST-11-025","text":"What are the dimensions of kinematic viscosity of a fluid?","options":[{"key":"a","text":"\\(\\mathrm{LT^{2}}\\)"},{"key":"b","text":"\\(\\mathrm{L^{2}T^{-1}}\\)"},{"key":"c","text":"\\(\\mathrm{ML^{-1}T^{-1}}\\)"},{"key":"d","text":"\\(\\mathrm{ML^{-2}T^{2}}\\)"}],"answer":"b","explanation":"Kinematic viscosity is \\(\\nu = \\dfrac{\\mu}{\\rho}\\), with dimensions \\[\\dfrac{\\text{ML}^{-1}\\text{T}^{-1}}{\\text{ML}^{-3}} = \\text{L}^2\\text{T}^{-1}\\] (m<sup>2</sup> per s, or stokes). \\(\\text{ML}^{-1}\\text{T}^{-1}\\) is dynamic viscosity.","marks":1,"source":{"kind":"past","set":11,"question":25,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q25 · 1 mark"},"topic":"ACiE0301"},{"id":"PAST-11-028","src":"PAST-11-028","text":"The hydraulic radius in a wide rectangular channel with channel bed \\(b\\) m wide, if the flow depth is \\(y\\), is","options":[{"key":"a","text":"\\(\\dfrac{by}{b + 2y}\\)"},{"key":"b","text":"\\(\\dfrac{y}{2}\\)"},{"key":"c","text":"\\(b\\)"},{"key":"d","text":"\\(y\\)"}],"answer":"d","explanation":"The hydraulic radius is \\[R = \\dfrac{by}{b + 2y}\\] For a wide channel (\\(b \\gg y\\)) this tends to \\(y\\), the flow depth.","marks":1,"source":{"kind":"past","set":11,"question":28,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q28 · 1 mark"},"topic":"ACiE0305"},{"id":"PAST-11-056","src":"PAST-11-056","text":"Time of concentration is the","options":[{"key":"a","text":"time of maximum possible precipitation that may concentrate and fall over a given basin"},{"key":"b","text":"time taken by the rain water to flow to an existing defined drain in a basin"},{"key":"c","text":"time for which the rain water remains concentrated on the basin"},{"key":"d","text":"maximum time taken by the rain water to reach the outlet of the basin"}],"answer":"d","explanation":"The time of concentration is the travel time from the hydraulically most remote point of the catchment to the outlet. After it, the whole basin contributes to the flow.","marks":1,"source":{"kind":"past","set":11,"question":56,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q56 · 1 mark"},"topic":"ACiE0306"},{"id":"PAST-11-058","src":"PAST-11-058","text":"In the Bernoulli equation used in pipe flow, each term represents","options":[{"key":"a","text":"work done per unit weight"},{"key":"b","text":"energy per unit mass"},{"key":"c","text":"work done per unit volume"},{"key":"d","text":"energy per unit flow length"}],"answer":"a","explanation":"The terms \\(\\dfrac{p}{\\gamma}\\), \\(\\dfrac{V^2}{2g}\\) and \\(z\\) are heads in metres, i.e. energy (work) per unit weight of the flowing fluid.","marks":1,"source":{"kind":"past","set":11,"question":58,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q58 · 1 mark"},"topic":"ACiE0303"},{"id":"PAST-11-065","src":"PAST-11-065","text":"Find the (absolute) pressure at a point if the suction pressure at that point is 100 kPa (\\(P_\\mathrm{atm} = 760\\) mm of Hg).","options":[{"key":"a","text":"1.4 Pa"},{"key":"b","text":"1.4 kPa"},{"key":"c","text":"101.4 kPa"},{"key":"d","text":"201.4 kPa"}],"answer":"b","explanation":"760 mm Hg is about 101.3-101.4 kPa, so \\[\\begin{aligned} p_{abs} &amp;= p_{atm} - \\text{suction} \\\\ &amp;\\approx 101.4 - 100 = 1.4\\ \\text{kPa} \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":11,"question":65,"marks":2,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q65 · 2 marks"},"topic":"ACiE0302"},{"id":"PAST-11-066","src":"PAST-11-066","text":"A jet of water issues from a nozzle with a velocity 'v' and impinges normally on a fixed flat plate. The cross-sectional area of the jet is 0.02 m<sup>2</sup> and the density of water is 1000 kg/m<sup>3</sup>. If the force developed on the plate is 2 kN, the velocity v is","options":[{"key":"a","text":"5 m/s"},{"key":"b","text":"10 m/s"},{"key":"c","text":"20 m/s"},{"key":"d","text":"25 m/s"}],"answer":"b","explanation":"For a jet striking a fixed plate normally, \\(F = \\rho aV^2\\). So \\[2000 = 1000 \\times 0.02 \\times V^2\\] giving \\(V = 10\\) m per s.","marks":2,"source":{"kind":"past","set":11,"question":66,"marks":2,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q66 · 2 marks"},"topic":"ACiE0303"}]},{"name":"Structural Mechanics","questions":[{"id":"PAST-11-009","src":"PAST-11-009","text":"The total strain energy stored in a body is known as","options":[{"key":"a","text":"resilience"},{"key":"b","text":"toughness"},{"key":"c","text":"modulus of resilience"},{"key":"d","text":"none of the above"}],"answer":"a","explanation":"Resilience is the total strain energy stored in a body under load. Proof resilience is its value at the elastic limit, and modulus of resilience is proof resilience per unit volume.","marks":1,"source":{"kind":"past","set":11,"question":9,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q9 · 1 mark"},"topic":"ACiE0402"},{"id":"PAST-11-027","src":"PAST-11-027","text":"Who published the moment distribution method?","options":[{"key":"a","text":"Castigliano"},{"key":"b","text":"Hardy Cross"},{"key":"c","text":"Bernoulli"},{"key":"d","text":"Euler"}],"answer":"b","explanation":"Hardy Cross introduced the moment distribution method in 1930 for analysing continuous beams and frames.","marks":1,"source":{"kind":"past","set":11,"question":27,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q27 · 1 mark"},"topic":"ACiE0406"},{"id":"PAST-11-034","src":"PAST-11-034","text":"The shear modulus is defined as the ratio of","options":[{"key":"a","text":"shear stress to shear strain"},{"key":"b","text":"shear strain to shear stress"},{"key":"c","text":"shear strain to longitudinal strain"},{"key":"d","text":"shear stress to longitudinal stress"}],"answer":"a","explanation":"Within the elastic limit, the modulus of rigidity is \\[G = \\dfrac{\\tau}{\\gamma}\\]","marks":1,"source":{"kind":"past","set":11,"question":34,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q34 · 1 mark"},"topic":"ACiE0402"},{"id":"PAST-11-037","src":"PAST-11-037","text":"The maximum deflection in a fixed beam due to a point load (\\(P\\) kN) at the centre is","options":[{"key":"a","text":"\\(\\dfrac{PL^3}{48EI}\\)"},{"key":"b","text":"\\(\\dfrac{PL^3}{192EI}\\)"},{"key":"c","text":"\\(\\dfrac{PL^2}{16EI}\\)"},{"key":"d","text":"\\(\\dfrac{PL^3}{384EI}\\)"}],"answer":"b","explanation":"End fixity cuts the central deflection to one quarter of the simply supported value: \\[\\delta = \\dfrac{PL^3}{192EI}\\] instead of \\(\\dfrac{PL^3}{48EI}\\).","marks":1,"source":{"kind":"past","set":11,"question":37,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q37 · 1 mark"},"topic":"ACiE0406"},{"id":"PAST-11-039","src":"PAST-11-039","text":"The ILD for the reaction at the support of a cantilever beam is a","options":[{"key":"a","text":"isosceles triangle"},{"key":"b","text":"right angled isosceles triangle"},{"key":"c","text":"rectangle"},{"key":"d","text":"parabolic"}],"answer":"c","explanation":"Wherever the unit load stands on a cantilever, the fixed-end reaction is 1. The ILD is therefore a rectangle of unit height over the length.","marks":1,"source":{"kind":"past","set":11,"question":39,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q39 · 1 mark"},"topic":"ACiE0404"},{"id":"PAST-11-044","src":"PAST-11-044","text":"The bending moment is independent of","options":[{"key":"a","text":"span"},{"key":"b","text":"loading"},{"key":"c","text":"type of beam"},{"key":"d","text":"beam section"}],"answer":"d","explanation":"Bending moment comes from statics: it depends on the loads, span and supports, but not on the cross-section of a determinate beam. The section governs the stresses, not the moment.","marks":1,"source":{"kind":"past","set":11,"question":44,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q44 · 1 mark"},"topic":"ACiE0401"},{"id":"PAST-11-067","src":"PAST-11-067","text":"A simply supported beam of span 4 m carries three point loads of 10 kN each at 1 m, 2 m and 3 m from the left support. The maximum BM is","options":[{"key":"a","text":"10 kNm"},{"key":"b","text":"15 kNm"},{"key":"c","text":"20 kNm"},{"key":"d","text":"25 kNm"}],"answer":"c","explanation":"By symmetry \\(R_A = R_B = 15\\) kN. The SF changes sign under the middle load, so \\[M_{max} = 15 \\times 2 - 10 \\times 1 = 20\\] kNm. (The paper shows only a sketch; the load values are those used in the key's working.)","marks":2,"source":{"kind":"past","set":11,"question":67,"marks":2,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q67 · 2 marks"},"topic":"ACiE0401"},{"id":"PAST-11-068","src":"PAST-11-068","text":"For a beam 24 m long, find the maximum negative SF at a section 8 m from the left support when a series of loads 8 kN, 15 kN, 15 kN and 10 kN move from left to right with 2 m between loads.","options":[{"key":"a","text":"10.25 kN"},{"key":"b","text":"6.25 kN"},{"key":"c","text":"4.25 kN"},{"key":"d","text":"42.25 kN"}],"answer":"a","explanation":"The ILD for shear at 8 m is negative to the left, with ordinate \\(-\\dfrac{x}{24}\\). With the 10 kN load at the section and the others 2, 4 and 6 m behind it, The weighted sum of loads times ordinate distances is \\[\\begin{aligned} &amp;10 \\times 8 + 15 \\times 6 \\\\ &amp;\\quad + 15 \\times 4 + 8 \\times 2 = 246 \\end{aligned}\\] so \\[\\text{SF} = -\\dfrac{246}{24} = -10.25\\ \\text{kN}\\]","marks":2,"source":{"kind":"past","set":11,"question":68,"marks":2,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q68 · 2 marks"},"topic":"ACiE0404"}]},{"name":"Design of Structures","questions":[{"id":"PAST-11-020","src":"PAST-11-020","text":"The abrasion test is conducted to find","options":[{"key":"a","text":"hardness of aggregates"},{"key":"b","text":"strength of aggregates"},{"key":"c","text":"toughness of aggregates"},{"key":"d","text":"durability of aggregates"}],"answer":"a","explanation":"The Los Angeles abrasion test measures the hardness (resistance to wear) of aggregates. Toughness is found by the impact test, strength by the crushing test and durability by the soundness test.","marks":1,"source":{"kind":"past","set":11,"question":20,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q20 · 1 mark"},"topic":"ACiE0502"},{"id":"PAST-11-040","src":"PAST-11-040","text":"Which part of Nepal is more susceptible to earthquake?","options":[{"key":"a","text":"Eastern Nepal"},{"key":"b","text":"Western Nepal"},{"key":"c","text":"Northern Nepal"},{"key":"d","text":"both a and b"}],"answer":"b","explanation":"Western Nepal lies in the central seismic gap, where no great earthquake has released the accumulated strain for centuries, so a large event is considered overdue there. The source key prints (a) but names 'Western Nepal', which is option (b).","marks":1,"source":{"kind":"past","set":11,"question":40,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q40 · 1 mark"},"topic":"ACiE0501"},{"id":"PAST-11-043","src":"PAST-11-043","text":"The effective length of a battened column is increased by","options":[{"key":"a","text":"10%"},{"key":"b","text":"7%"},{"key":"c","text":"12%"},{"key":"d","text":"25%"}],"answer":"a","explanation":"Battened columns are less rigid in shear than laced ones, so IS 800 increases their effective length by 10%.","marks":1,"source":{"kind":"past","set":11,"question":43,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q43 · 1 mark"},"topic":"ACiE0505"},{"id":"PAST-11-048","src":"PAST-11-048","text":"The minimum cover for a slab is","options":[{"key":"a","text":"15 mm"},{"key":"b","text":"20 mm"},{"key":"c","text":"40 mm"},{"key":"d","text":"50 mm"}],"answer":"a","explanation":"The key takes 15 mm, the traditional minimum clear cover for slab steel (and not less than the bar diameter). IS 456:2000 specifies 20 mm nominal cover for mild exposure, reducible to 15 mm for bars up to 12 mm.","marks":1,"source":{"kind":"past","set":11,"question":48,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q48 · 1 mark"},"topic":"ACiE0503"},{"id":"PAST-11-055","src":"PAST-11-055","text":"What is the minimum pitch distance?","options":[{"key":"a","text":"2.0 × nominal diameter of fastener"},{"key":"b","text":"3.0 × nominal diameter of fastener"},{"key":"c","text":"1.5 × nominal diameter of fastener"},{"key":"d","text":"2.5 × nominal diameter of fastener"}],"answer":"d","explanation":"IS 800 requires the distance between centres of fasteners to be at least 2.5 times their nominal diameter.","marks":1,"source":{"kind":"past","set":11,"question":55,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q55 · 1 mark"},"topic":"ACiE0505"},{"id":"PAST-11-069","src":"PAST-11-069","text":"The mandatory rules of thumb for load-bearing masonry are given in","options":[{"key":"a","text":"NBC 105"},{"key":"b","text":"NBC 202"},{"key":"c","text":"NBC 203"},{"key":"d","text":"NBC 204"}],"answer":"b","explanation":"NBC 202 gives the mandatory rules of thumb for load-bearing masonry buildings. NBC 105 is the seismic design code, and NBC 203 and 204 cover low-strength and earthen buildings.","marks":2,"source":{"kind":"past","set":11,"question":69,"marks":2,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q69 · 2 marks"},"topic":"ACiE0506"}]},{"name":"Water Supply, Sanitation and Environment","questions":[{"id":"PAST-11-011","src":"PAST-11-011","text":"Which of the following is not generated during wastewater treatment?","options":[{"key":"a","text":"Sludge"},{"key":"b","text":"Scum"},{"key":"c","text":"Potable water"},{"key":"d","text":"Clarified water"}],"answer":"c","explanation":"Sewage treatment produces sludge, scum and a clarified effluent that is fit for disposal, not potable (drinking) water.","marks":1,"source":{"kind":"past","set":11,"question":11,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q11 · 1 mark"},"topic":"ACiE0605"},{"id":"PAST-11-016","src":"PAST-11-016","text":"Algae in a pond","options":[{"key":"a","text":"float in the water during day time and sink during night time"},{"key":"b","text":"float in the water during night time and sink during day time"},{"key":"c","text":"float in the water during day time and night time"},{"key":"d","text":"sink in the water during day time and night time"}],"answer":"a","explanation":"Photosynthesis by day fills algal cells with oxygen bubbles, so they rise and float. At night respiration uses up the gas and they sink.","marks":1,"source":{"kind":"past","set":11,"question":16,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q16 · 1 mark"},"topic":"ACiE0601"},{"id":"PAST-11-017","src":"PAST-11-017","text":"For controlling the growth of algae, the chemical generally used is","options":[{"key":"a","text":"alum"},{"key":"b","text":"bleaching powder"},{"key":"c","text":"lime"},{"key":"d","text":"copper sulphate"}],"answer":"d","explanation":"Copper sulphate (about 0.3–0.5 mg/L) is the standard algicide for reservoirs and ponds. It is often dragged through the water in gunny bags.","marks":1,"source":{"kind":"past","set":11,"question":17,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q17 · 1 mark"},"topic":"ACiE0603"},{"id":"PAST-11-021","src":"PAST-11-021","text":"Which type of hazard is an earthquake and landslide?","options":[{"key":"a","text":"Meteorological"},{"key":"b","text":"Hydrological"},{"key":"c","text":"Geological"},{"key":"d","text":"Biological"}],"answer":"c","explanation":"Earthquakes and landslides arise from earth processes (crustal movement and slope instability), so they are geological (geophysical) hazards. Floods are hydrological and storms meteorological.","marks":1,"source":{"kind":"past","set":11,"question":21,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q21 · 1 mark"},"topic":"ACiE0606"},{"id":"PAST-11-031","src":"PAST-11-031","text":"The unit of measurement of odour is","options":[{"key":"a","text":"TON"},{"key":"b","text":"NTU"},{"key":"c","text":"FTU"},{"key":"d","text":"ppm"}],"answer":"a","explanation":"Odour is reported as the threshold odour number (TON): the dilution ratio at which the odour is just detectable. NTU and FTU are turbidity units.","marks":1,"source":{"kind":"past","set":11,"question":31,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q31 · 1 mark"},"topic":"ACiE0601"},{"id":"PAST-11-038","src":"PAST-11-038","text":"NTU is the measure of","options":[{"key":"a","text":"turbidity"},{"key":"b","text":"colour"},{"key":"c","text":"dissolved oxygen"},{"key":"d","text":"pH"}],"answer":"a","explanation":"Nephelometric turbidity units measure the light scattered by suspended particles, i.e. turbidity. Colour is in Hazen (Pt–Co) units.","marks":1,"source":{"kind":"past","set":11,"question":38,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q38 · 1 mark"},"topic":"ACiE0601"},{"id":"PAST-11-050","src":"PAST-11-050","text":"For a given discharge, the efficiency of a sedimentation tank can be increased by","options":[{"key":"a","text":"increasing the depth of the tank"},{"key":"b","text":"increasing the surface area of the tank"},{"key":"c","text":"decreasing the depth of the tank"},{"key":"d","text":"decreasing the surface area of the tank"}],"answer":"b","explanation":"Removal depends on the overflow rate Q/A. A larger surface area means a lower overflow rate, so more (finer) particles settle; depth has no effect in ideal settling.","marks":1,"source":{"kind":"past","set":11,"question":50,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q50 · 1 mark"},"topic":"ACiE0603"},{"id":"PAST-11-071","src":"PAST-11-071","text":"In a rapid sand filter, the rate of filtration ranges from","options":[{"key":"a","text":"100 to 200 liter/hr/m<sup>2</sup>"},{"key":"b","text":"3000 to 6000 liter/hr/m<sup>2</sup>"},{"key":"c","text":"8000 to 15000 liter/hr/m<sup>2</sup>"},{"key":"d","text":"180 to 360 liter/hr/m<sup>2</sup>"}],"answer":"b","explanation":"Rapid sand filters work at about 3000-6000 litres per hour per m<sup>2</sup>, roughly 30 times the 100-200 litres per hour per m<sup>2</sup> of slow sand filters.","marks":2,"source":{"kind":"past","set":11,"question":71,"marks":2,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q71 · 2 marks"},"topic":"ACiE0603"},{"id":"PAST-11-072","src":"PAST-11-072","text":"Usually, while designing, what is the range of length of the aerated grit chamber assumed?","options":[{"key":"a","text":"7.5-20 m"},{"key":"b","text":"4-6 m"},{"key":"c","text":"25 m"},{"key":"d","text":"50 m"}],"answer":"a","explanation":"Aerated grit chambers are typically designed 7.5–20 m long, with a depth of 2–5 m and a detention time of about 2–5 minutes at peak flow.","marks":2,"source":{"kind":"past","set":11,"question":72,"marks":2,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q72 · 2 marks"},"topic":"ACiE0605"}]},{"name":"Irrigation and Drainage","questions":[{"id":"PAST-11-041","src":"PAST-11-041","text":"A fish ladder is provided on the side of the","options":[{"key":"a","text":"divide wall"},{"key":"b","text":"diaphragm wall"},{"key":"c","text":"core wall"},{"key":"d","text":"wing wall"}],"answer":"a","explanation":"A fish ladder (a stepped or baffled channel) is built next to the divide wall at the weir, so that fish can pass up and down the river.","marks":1,"source":{"kind":"past","set":11,"question":41,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q41 · 1 mark"},"topic":"ACiE0703"},{"id":"PAST-11-046","src":"PAST-11-046","text":"The purpose of constructing a 'groyne' is to","options":[{"key":"a","text":"expand a river channel to improve its depth"},{"key":"b","text":"encourage meandering"},{"key":"c","text":"train the flow along a certain course"},{"key":"d","text":"reduce the silting in the river bed"}],"answer":"c","explanation":"Groynes (spurs) project from the bank to deflect the current away from it and hold the river to a desired course. They also cause silting between the spurs, protecting the bank.","marks":1,"source":{"kind":"past","set":11,"question":46,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q46 · 1 mark"},"topic":"ACiE0704"},{"id":"PAST-11-047","src":"PAST-11-047","text":"The water which can be utilized by the crops from the soil is called","options":[{"key":"a","text":"field capacity water"},{"key":"b","text":"capillary water"},{"key":"c","text":"hygroscopic water"},{"key":"d","text":"none of the above"}],"answer":"b","explanation":"Plants use capillary water, held in the pores by surface tension between field capacity and the wilting point. Hygroscopic water is too tightly held, and gravity water drains away.","marks":1,"source":{"kind":"past","set":11,"question":47,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q47 · 1 mark"},"topic":"ACiE0701"},{"id":"PAST-11-051","src":"PAST-11-051","text":"In which stage of a river are sediments deposited?","options":[{"key":"a","text":"Rocky stage"},{"key":"b","text":"Boulder stage"},{"key":"c","text":"Trough stage"},{"key":"d","text":"Delta stage"}],"answer":"d","explanation":"Near its mouth the river's slope and velocity are lowest, so it deposits its load and builds a delta. The upper (rocky and boulder) stages erode.","marks":1,"source":{"kind":"past","set":11,"question":51,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q51 · 1 mark"},"topic":"ACiE0704"},{"id":"PAST-11-052","src":"PAST-11-052","text":"…… is a method of surface drainage which makes use of dead furrows.","options":[{"key":"a","text":"Outlet drains"},{"key":"b","text":"Surface outlet"},{"key":"c","text":"Bedding"},{"key":"d","text":"French drain"}],"answer":"c","explanation":"In bedding, land is ploughed into raised beds with dead furrows between them, which carry off excess surface water.","marks":1,"source":{"kind":"past","set":11,"question":52,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q52 · 1 mark"},"topic":"ACiE0706"},{"id":"PAST-11-053","src":"PAST-11-053","text":"A canal normally used for diversion of flood water of a river is","options":[{"key":"a","text":"feeder canal"},{"key":"b","text":"inundation canal"},{"key":"c","text":"ridge canal"},{"key":"d","text":"contour canal"}],"answer":"b","explanation":"Inundation canals draw water only when the river is high (in floods), without any weir. Feeder canals supply other canals.","marks":1,"source":{"kind":"past","set":11,"question":53,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q53 · 1 mark"},"topic":"ACiE0702"},{"id":"PAST-11-073","src":"PAST-11-073","text":"The length of base of an impervious floor is 60 m and it has a sheet pile of depth 8 m d/s. Find the residual head at the bottom of the sheet pile using Khosla's theory.","options":[{"key":"a","text":"22.2%"},{"key":"b","text":"32.1%"},{"key":"c","text":"67.9%"},{"key":"d","text":"77.8%"}],"answer":"a","explanation":"Here \\(\\alpha = \\dfrac{b}{d} = 7.5\\), so \\[\\lambda = \\dfrac{1 + \\sqrt{1 + \\alpha^2}}{2} = 4.283\\] At the bottom of the end pile, \\[\\begin{aligned} \\phi_D &amp;= \\dfrac{1}{\\pi}\\cos^{-1}\\left(\\dfrac{\\lambda - 1}{\\lambda}\\right) \\\\ &amp;\\approx 0.222 \\end{aligned}\\] or 22.2%. At its upstream junction, \\[\\phi_E = \\dfrac{1}{\\pi}\\cos^{-1}\\left(\\dfrac{\\lambda - 2}{\\lambda}\\right)\\] about 32.1%.","marks":2,"source":{"kind":"past","set":11,"question":73,"marks":2,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q73 · 2 marks"},"topic":"ACiE0703"},{"id":"PAST-11-074","src":"PAST-11-074","text":"A canal irrigates 100 ha, delivering 100 lps/ha. What is the average boundary shear stress for a rectangular canal having bed slope 1 in 3000, Manning's coefficient \\(n = 0.025\\) and \\(B/D\\) ratio of 3?","options":[{"key":"a","text":"1.20 N/m<sup>2</sup>"},{"key":"b","text":"2.94 N/m<sup>2</sup>"},{"key":"c","text":"3.94 N/m<sup>2</sup>"},{"key":"d","text":"6.02 N/m<sup>2</sup>"}],"answer":"c","explanation":"The discharge is \\(Q = 10\\) m<sup>3</sup> per s. With \\(D = \\dfrac{B}{3}\\), \\(A = \\dfrac{B^2}{3}\\) and \\(R = \\dfrac{B}{5}\\). Manning then gives \\(B \\approx 6.02\\) m and \\(R \\approx 1.205\\) m, so \\[\\begin{aligned} \\tau_0 &amp;= \\gamma RS = \\dfrac{9810 \\times 1.205}{3000} \\\\ &amp;\\approx 3.94\\ \\text{N/m}^2 \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":11,"question":74,"marks":2,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q74 · 2 marks"},"topic":"ACiE0702"}]},{"name":"Hydropower","questions":[{"id":"PAST-11-029","src":"PAST-11-029","text":"The annual depreciation in a hydropower plant is","options":[{"key":"a","text":"0.5–1.5%"},{"key":"b","text":"5–10%"},{"key":"c","text":"10–20%"},{"key":"d","text":"25–30%"}],"answer":"a","explanation":"Hydropower works (dams, tunnels, powerhouses) have very long lives, so their annual depreciation is only about 0.5–1.5%, far lower than for diesel or thermal plants.","marks":1,"source":{"kind":"past","set":11,"question":29,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q29 · 1 mark"},"topic":"ACiE0802"},{"id":"PAST-11-035","src":"PAST-11-035","text":"Pick up the incorrect statement from the following during tunnel excavation.","options":[{"key":"a","text":"Oxygen should not be less than 19.5%"},{"key":"b","text":"Carbon dioxide should not be more than 0.5%"},{"key":"c","text":"Hydrogen sulphide should not be more than 0.001%"},{"key":"d","text":"Oxygen should be less than 19.5%"}],"answer":"d","explanation":"Tunnel air must contain at least 19.5% oxygen, so saying it 'should be less than 19.5%' is wrong. The CO<sub>2</sub> and H<sub>2</sub>S limits are correct.","marks":1,"source":{"kind":"past","set":11,"question":35,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q35 · 1 mark"},"topic":"ACiE0805"},{"id":"PAST-11-045","src":"PAST-11-045","text":"A …… is a structure used to provide for the controlled release of flows from a dam or levee into a downstream area.","options":[{"key":"a","text":"weir"},{"key":"b","text":"sluice"},{"key":"c","text":"spillway"},{"key":"d","text":"approach"}],"answer":"c","explanation":"A spillway safely releases surplus flood water from a reservoir to the downstream river, protecting the dam from overtopping.","marks":1,"source":{"kind":"past","set":11,"question":45,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q45 · 1 mark"},"topic":"ACiE0803"},{"id":"PAST-11-075","src":"PAST-11-075","text":"Calculate the revenue generated by hydropower if water is continually supplied at a rate of 100 m<sup>3</sup>/s. The head available is 75 m. The capacity factor is 0.5, the hydropower runs for 3 hours and the rate of electricity is Rs 18 per unit.","options":[{"key":"a","text":"1.55 million"},{"key":"b","text":"1.98 million"},{"key":"c","text":"2.55 million"},{"key":"d","text":"2.35 million"}],"answer":"b","explanation":"The hydraulic power is \\[\\begin{aligned} P &amp;= \\rho gQH \\\\ &amp;= 1000 \\times 9.81 \\times 100 \\times 75 \\\\ &amp;\\approx 73.6\\ \\text{MW} \\end{aligned}\\] At a capacity factor of 0.5 the output is 36.8 MW; over 3 h that is about 110,250 kWh, and at Rs 18 per unit the revenue is about Rs 1.98 million. The source key prints (c), but its own working gives 1.98 million, option (b).","marks":2,"source":{"kind":"past","set":11,"question":75,"marks":2,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q75 · 2 marks"},"topic":"ACiE0802"},{"id":"PAST-11-076","src":"PAST-11-076","text":"Governors are used in power plants to directly","options":[{"key":"a","text":"reduce carbon emissions"},{"key":"b","text":"decrease the power consumption"},{"key":"c","text":"control the flow of working fluids"},{"key":"d","text":"generate the working fluids"}],"answer":"c","explanation":"A governor senses speed changes with load and adjusts the flow of working fluid (water through the wicket gates or spear valve), keeping the mean speed constant.","marks":2,"source":{"kind":"past","set":11,"question":76,"marks":2,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q76 · 2 marks"},"topic":"ACiE0806"}]},{"name":"Transportation","questions":[{"id":"PAST-11-006","src":"PAST-11-006","text":"If the speed of the overtaken vehicle is 80 kmph, then the design speed is","options":[{"key":"a","text":"80 kmph"},{"key":"b","text":"96 kmph"},{"key":"c","text":"100 kmph"},{"key":"d","text":"106 kmph"}],"answer":"b","explanation":"For overtaking sight distance, the overtaken vehicle is assumed to travel 16 km per h slower than the design speed, so the design speed is \\[80 + 16 = 96\\ \\text{km/h}\\]","marks":1,"source":{"kind":"past","set":11,"question":6,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q6 · 1 mark"},"topic":"ACiE0902"},{"id":"PAST-11-013","src":"PAST-11-013","text":"The best suited material for stabilization of black cotton soils is","options":[{"key":"a","text":"sodium silicate"},{"key":"b","text":"calcium chloride"},{"key":"c","text":"hydrated lime"},{"key":"d","text":"bitumen"}],"answer":"c","explanation":"Lime reacts with the montmorillonite clay of black cotton soil through cation exchange and pozzolanic action. This reduces its plasticity and swelling and increases its strength.","marks":1,"source":{"kind":"past","set":11,"question":13,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q13 · 1 mark"},"topic":"ACiE0906"},{"id":"PAST-11-032","src":"PAST-11-032","text":"The densification of a soil by means of mechanical manipulation is called","options":[{"key":"a","text":"compressibility"},{"key":"b","text":"soil stabilization"},{"key":"c","text":"compression"},{"key":"d","text":"compaction"}],"answer":"d","explanation":"Compaction is densification by mechanical means (rolling, tamping, vibration) that expels air. Consolidation is expulsion of water under sustained load.","marks":1,"source":{"kind":"past","set":11,"question":32,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q32 · 1 mark"},"topic":"ACiE0906"},{"id":"PAST-11-042","src":"PAST-11-042","text":"Which of the following is considered to be the highest quality construction in the group of black top pavements?","options":[{"key":"a","text":"Mastic asphalt"},{"key":"b","text":"Sheet asphalt"},{"key":"c","text":"Bituminous carpet"},{"key":"d","text":"Bituminous concrete"}],"answer":"d","explanation":"Bituminous (asphaltic) concrete is a dense, well-graded, hot-mixed and carefully controlled mix. It is the highest quality bituminous surfacing.","marks":1,"source":{"kind":"past","set":11,"question":42,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q42 · 1 mark"},"topic":"ACiE0905"},{"id":"PAST-11-054","src":"PAST-11-054","text":"Dowel bars are provided at","options":[{"key":"a","text":"expansion joints"},{"key":"b","text":"contraction joints"},{"key":"c","text":"both (1) and (2)"},{"key":"d","text":"both (1) and (2) and longitudinal joints"}],"answer":"c","explanation":"Dowels transfer wheel loads across transverse joints (both expansion and contraction joints) in concrete pavements. Longitudinal joints use tie bars.","marks":1,"source":{"kind":"past","set":11,"question":54,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q54 · 1 mark"},"topic":"ACiE0905"},{"id":"PAST-11-077","src":"PAST-11-077","text":"A two-lane single carriageway is to be designed for a design life period of 15 years. The total two way traffic intensity in the year of completion of construction is expected to be 2000 commercial vehicles per day. Vehicle damage factor = 3.0 and lane distribution factor = 0.75. Assuming an annual rate of traffic growth of 7.5%, the design traffic expressed as the cumulative number of standard axles is","options":[{"key":"a","text":"22.6 × 10<sup>6</sup>"},{"key":"b","text":"5.3 × 10<sup>6</sup>"},{"key":"c","text":"42.9 × 10<sup>6</sup>"},{"key":"d","text":"10.1 × 10<sup>6</sup>"}],"answer":"c","explanation":"The cumulative standard axles are \\[N = 365A\\dfrac{(1 + r)^n - 1}{r}DF\\] The growth factor is \\[\\dfrac{1.075^{15} - 1}{0.075} = 26.12\\] and \\(DF = 0.75 \\times 3 = 2.25\\), so \\[\\begin{aligned} N &amp;= 365 \\times 2000 \\\\ &amp;\\quad \\times 26.12 \\times 2.25 \\\\ &amp;\\approx 42.9 \\times 10^6 \\end{aligned}\\]","marks":2,"source":{"kind":"past","set":11,"question":77,"marks":2,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q77 · 2 marks"},"topic":"ACiE0905"},{"id":"PAST-11-078","src":"PAST-11-078","text":"The stopping sight distance (SSD) for a level highway is 140 m for the design speed of 90 km/h. The acceleration due to gravity and deceleration rate are 9.81 m/s<sup>2</sup> and 3.5 m/s<sup>2</sup>, respectively. The perception/reaction time (in s, rounded off to two decimal places) used in the SSD calculation is","options":[{"key":"a","text":"2.00 sec"},{"key":"b","text":"2.03 sec"},{"key":"c","text":"2.50 sec"},{"key":"d","text":"2.53 sec"}],"answer":"b","explanation":"Here \\(v = 25\\) m per s and the braking distance is \\[\\dfrac{v^2}{2a} = \\dfrac{625}{7} = 89.3\\ \\text{m}\\] So \\[25t = 140 - 89.3 = 50.7\\] and \\(t \\approx 2.03\\) s.","marks":2,"source":{"kind":"past","set":11,"question":78,"marks":2,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q78 · 2 marks"},"topic":"ACiE0902"}]},{"name":"Project Planning, Design and Implementation","questions":[{"id":"PAST-11-004","src":"PAST-11-004","text":"The number of articles in the NEC code of conduct as updated in 2079 BS is","options":[{"key":"a","text":"5"},{"key":"b","text":"8"},{"key":"c","text":"11"},{"key":"d","text":"13"}],"answer":"c","explanation":"The 2079 BS revision raised NEC's professional code of conduct from 8 to 11 articles.","marks":1,"source":{"kind":"past","set":11,"question":4,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q4 · 1 mark"},"topic":"AALL1005"},{"id":"PAST-11-010","src":"PAST-11-010","text":"Which of the following measures are used by a risk-averse person to minimize risk? (A) Diversification of resources (B) Insurance of risk event (C) Total cost of resources (D) Value of information of risk event","options":[{"key":"a","text":"A, B and C only"},{"key":"b","text":"A, B and D only"},{"key":"c","text":"B, C and D only"},{"key":"d","text":"A, C and D only"}],"answer":"b","explanation":"A risk-averse person spreads resources (diversification), transfers risk (insurance) and buys information to reduce uncertainty. 'Total cost of resources' is not a risk-reduction measure.","marks":1,"source":{"kind":"past","set":11,"question":10,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q10 · 1 mark"},"topic":"AALL1004"},{"id":"PAST-11-019","src":"PAST-11-019","text":"As the benefit cost ratio of a project increases, the attractiveness of the project increases. But the minimum value of benefit cost ratio should be …… for acceptance of the project.","options":[{"key":"a","text":"less than one"},{"key":"b","text":"one"},{"key":"c","text":"greater than one"},{"key":"d","text":"none of the above"}],"answer":"b","explanation":"A project is acceptable when the B/C ratio is at least 1, i.e. when discounted benefits at least equal discounted costs. Higher ratios are more attractive.","marks":1,"source":{"kind":"past","set":11,"question":19,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q19 · 1 mark"},"topic":"AALL1002"},{"id":"PAST-11-026","src":"PAST-11-026","text":"The fine for violating patient rights is","options":[{"key":"a","text":"100000"},{"key":"b","text":"250000"},{"key":"c","text":"500000"},{"key":"d","text":"1000000"}],"answer":"c","explanation":"The source quotes a fine of up to Rs 5,00,000 for the main offence (Rs 2,50,000 for attempt or abetment). This is a law-based question outside core engineering.","marks":1,"source":{"kind":"past","set":11,"question":26,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q26 · 1 mark"},"topic":"AALL1005"},{"id":"PAST-11-030","src":"PAST-11-030","text":"A sinking fund is","options":[{"key":"a","text":"the fund for rebuilding a structure when its economic life is over"},{"key":"b","text":"raised to meet maintenance costs"},{"key":"c","text":"the total sum to be paid to the municipal authorities by the tenants"},{"key":"d","text":"a part of the money kept in reserve for providing additional structures and structural modifications"}],"answer":"a","explanation":"A sinking fund is set aside periodically (earning interest) so that the property can be rebuilt or replaced when its economic life ends.","marks":1,"source":{"kind":"past","set":11,"question":30,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q30 · 1 mark"},"topic":"AALL1002"},{"id":"PAST-11-049","src":"PAST-11-049","text":"The rules of ethics are also called","options":[{"key":"a","text":"rules"},{"key":"b","text":"law"},{"key":"c","text":"responsibility"},{"key":"d","text":"none of the above"}],"answer":"b","explanation":"Ethical rules are sometimes called moral law: principles of right conduct that guide behaviour, although, unlike legal law, they are not enforced by the state.","marks":1,"source":{"kind":"past","set":11,"question":49,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q49 · 1 mark"},"topic":"AALL1005"},{"id":"PAST-11-057","src":"PAST-11-057","text":"Which of the following statement(s) is/are incorrect? (i) The earliest start of an activity is the early event time of the node it leaves. (ii) The latest finish of an activity is the late event time of the node it enters. (iii) The latest start of an activity is its latest finish minus its duration.","options":[{"key":"a","text":"Only (i)"},{"key":"b","text":"(i) and (ii)"},{"key":"c","text":"(ii) and (iii)"},{"key":"d","text":"None"}],"answer":"d","explanation":"All three are correct definitions: EST is the early time of the tail node, LFT is the late time of the head node, and \\[\\text{LST} = \\text{LFT} - D\\]","marks":1,"source":{"kind":"past","set":11,"question":57,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q57 · 1 mark"},"topic":"AALL1003"},{"id":"PAST-11-059","src":"PAST-11-059","text":"Pick up the incorrect statement from the following.","options":[{"key":"a","text":"The activity is the time-consuming part of a project"},{"key":"b","text":"The beginning and end of a job are called events"},{"key":"c","text":"The activity which consumes maximum time is called a node"},{"key":"d","text":"Logically and sequentially connected activities and events form a network"}],"answer":"c","explanation":"A node is an event, an instant with no duration, not a time-consuming activity. The other statements are correct.","marks":1,"source":{"kind":"past","set":11,"question":59,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q59 · 1 mark"},"topic":"AALL1003"},{"id":"PAST-11-060","src":"PAST-11-060","text":"\"Risk management\" is a process that includes","options":[{"key":"a","text":"Hazard identification"},{"key":"b","text":"Interactive exchange of information and opinions"},{"key":"c","text":"Hazard characterization"},{"key":"d","text":"Evaluation of policy alternatives"}],"answer":"d","explanation":"In risk analysis, hazard identification and characterisation belong to risk assessment, and the exchange of information and opinions is risk communication. Risk management weighs and selects policy alternatives.","marks":1,"source":{"kind":"past","set":11,"question":60,"marks":1,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q60 · 1 mark"},"topic":"AALL1004"},{"id":"PAST-11-079","src":"PAST-11-079","text":"Resource smoothing is","options":[{"key":"a","text":"an optimization and economical utilization of resources"},{"key":"b","text":"an adjustment of resources without affecting project duration"},{"key":"c","text":"a gradual increase in resources"},{"key":"d","text":"a gradual decrease in resources"}],"answer":"b","explanation":"Resource smoothing reschedules non-critical activities within their floats to level resource demand, keeping the project duration unchanged.","marks":2,"source":{"kind":"past","set":11,"question":79,"marks":2,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q79 · 2 marks"},"topic":"AALL1003"},{"id":"PAST-11-080","src":"PAST-11-080","text":"The estimated time \\(T_e\\) can be found if \\(T_o\\), \\(T_p\\) and \\(T_m\\) are given in a PERT activity as","options":[{"key":"a","text":"\\(T_e = \\dfrac{T_o + T_p + 2T_m}{6}\\)"},{"key":"b","text":"\\(T_e ={}\\) \\(\\dfrac{2T_o + 2T_p + 4T_m}{6}\\)"},{"key":"c","text":"\\(T_e = \\dfrac{T_o + 4T_p + T_m}{6}\\)"},{"key":"d","text":"\\(T_e = \\dfrac{T_o + T_p + 4T_m}{6}\\)"}],"answer":"d","explanation":"The \\(\\beta\\)-distribution gives the expected time \\[t_e = \\dfrac{t_o + 4t_m + t_p}{6}\\] with the most likely time weighted four times.","marks":2,"source":{"kind":"past","set":11,"question":80,"marks":2,"date":"2080 Chaitra 1","shift":"1st shift","reference":"Past Paper Set 11, Q80 · 2 marks"},"topic":"AALL1003"}]}]};
